/**
 * Generates `src/internal/proxyProcessSource.ts`, the source text of the
 * proxy process program that the default launcher runs with `node -e`, from
 * `src/internal/proxyProcessWorker.ts`. Run by `pnpm codegen`. With
 * `--check`, exits with code 1 if the generated file is out of date.
 */
import * as Fs from "node:fs"
import * as Module from "node:module"

const worker = new URL("../src/internal/proxyProcessWorker.ts", import.meta.url)
const output = new URL("../src/internal/proxyProcessSource.ts", import.meta.url)

// Node's type stripper blanks types with spaces at the same offsets. Comparing
// against the original text removes only the blanked spans and type-only lines,
// leaving string literals and comments untouched.
const stripTypes = (source: string): string => {
  const sourceLines = source.split("\n")
  const strippedLines = Module.stripTypeScriptTypes(source).split("\n")
  const lines: Array<string> = []
  let droppedTypeLine = false
  for (let i = 0; i < sourceLines.length; i++) {
    const original = sourceLines[i]
    const clean = strippedLines[i]
    if (original.trim().length > 0 && clean.trim().length === 0) {
      droppedTypeLine = true
      continue
    }
    if (droppedTypeLine && clean.length === 0 && (lines.length === 0 || lines.at(-1) === "")) {
      continue
    }
    droppedTypeLine = false
    let line = ""
    let j = 0
    while (j < clean.length) {
      if (clean[j] !== " ") {
        line += clean[j++]
        continue
      }
      let end = j
      let hadStripped = false
      while (end < clean.length && clean[end] === " ") {
        if (original[end] !== " ") hadStripped = true
        end++
      }
      if (!hadStripped) {
        line += clean.slice(j, end)
      } else {
        const next = clean[end] ?? ""
        if (next !== "" && (original[end - 1] === " " || (original[j] === " " && !/^[)\]},;.]/.test(next)))) {
          line += " "
        }
      }
      j = end
    }
    lines.push(line)
  }
  return lines.join("\n")
}

// The source text of the program, as an ES module that calls `run`.
const program = stripTypes(Fs.readFileSync(worker, "utf8")) + "\nrun()\n"

const escape = (text: string) => text.replace(/[\\`]|\$\{/g, (match) => "\\" + match)

if (process.argv.includes("--check")) {
  const { source } = await import(output.href)
  if (source !== program) {
    process.stderr.write("src/internal/proxyProcessSource.ts is out of date; run pnpm codegen\n")
    process.exitCode = 1
  }
} else {
  Fs.writeFileSync(
    output,
    `// Generated by scripts/generateProxyProcessSource.ts from proxyProcessWorker.ts. Do not edit.

/** @internal */
export const source = \`${escape(program)}\`
`
  )
}
